#pragma once
// Erase and program the CH643's own code flash, one 256-byte page at a
// time (fast erase / fast programming, CH643RM 20.4.5 and 20.4.6). Used by
// store.c for the item store in the top 32 KB.
//
// The project linker script (generated by the Makefile) limits FLASH to
// 30K and reserves this region as STORE, so the link fails if the
// firmware grows into it -- keep the Makefile's STORE_MEMORY_LINES in sync
// with these values.
#include <stdint.h>

#define STORE_FLASH_BASE 0x08007800u  // 0x08000000 + (62*1024 - 32*1024)
#define STORE_FLASH_SIZE 0x8000u      // 32KB
#define FLASH_PAGE_SIZE 256u

// Erases the page at addr (page-aligned), unless it is erased (all 0xFF)
// already.
void FlashPages_Erase(uint32_t addr);

// Programs one FLASH_PAGE_SIZE page at addr (page-aligned, erased).
void FlashPages_Program(uint32_t addr, const uint8_t* data);
